constexpr int kBinSize = 16;
constexpr float kEpsilon = 1e-6f;

real3<T> extent = bmax - bmin;
real3<T> inv_extent;
if (extent[0] > kEpsilon) inv_extent[0] = 1.0f / extent[0];
else inv_extent[0] = 0.0f;
if (extent[1] > kEpsilon) inv_extent[1] = 1.0f / extent[1];
else inv_extent[1] = 0.0f;
if (extent[2] > kEpsilon) inv_extent[2] = 1.0f / extent[2];
else inv_extent[2] = 0.0f;

T bin_width[3];
bin_width[0] = extent[0] / static_cast<T>(kBinSize);
bin_width[1] = extent[1] / static_cast<T>(kBinSize);
bin_width[2] = extent[2] / static_cast<T>(kBinSize);

int total_prims = bins->num_primitives();
if (total_prims <= 1) return false;

T min_cost = std::numeric_limits<T>::max();
int best_axis = -1;
real3<T> best_cut_pos;

for (int axis = 0; axis < 3; ++axis) {
    if (extent[axis] <= kEpsilon) continue;

    // Initialize bin counters
    std::fill(bins->bin_counts()[axis], bins->bin_counts()[axis] + kBinSize, 0);
    std::fill(bins->bin_start()[axis], bins->bin_start()[axis] + kBinSize, 0);
    std::fill(bins->bin_end()[axis], bins->bin_end()[axis] + kBinSize, 0);

    // Bin primitives
    for (int i = 0; i < total_prims; ++i) {
        T center = bins->bin_centers()[axis][i];
        int bin_idx = static_cast<int>((center - bmin[axis]) * inv_extent[axis] * static_cast<T>(kBinSize));
        if (bin_idx < 0) bin_idx = 0;
        if (bin_idx >= kBinSize) bin_idx = kBinSize - 1;
        bins->bin_counts()[axis][bin_idx]++;
    }

    // Compute prefix sums for left and right counts
    int left_count = 0;
    for (int i = 0; i < kBinSize - 1; ++i) {
        left_count += bins->bin_counts()[axis][i];
        int right_count = total_prims - left_count;
        if (left_count == 0 || right_count == 0) continue;

        // Compute SAH cost
        T left_area = 1.0f;
        T right_area = 1.0f;
        T cut_pos = bmin[axis] + (i + 1) * bin_width[axis];
        real3<T> left_extent = bmax - bmin;
        real3<T> right_extent = bmax - bmin;
        left_extent[axis] = cut_pos - bmin[axis];
        right_extent[axis] = bmax[axis] - cut_pos;

        if (left_extent[0] < kEpsilon) left_extent[0] = kEpsilon;
        if (left_extent[1] < kEpsilon) left_extent[1] = kEpsilon;
        if (left_extent[2] < kEpsilon) left_extent[2] = kEpsilon;
        if (right_extent[0] < kEpsilon) right_extent[0] = kEpsilon;
        if (right_extent[1] < kEpsilon) right_extent[1] = kEpsilon;
        if (right_extent[2] < kEpsilon) right_extent[2] = kEpsilon;

        left_area = 2.0f * (left_extent[0] * left_extent[1] + left_extent[1] * left_extent[2] + left_extent[2] * left_extent[0]);
        right_area = 2.0f * (right_extent[0] * right_extent[1] + right_extent[1] * right_extent[2] + right_extent[2] * right_extent[0]);

        T cost = left_area * static_cast<T>(left_count) + right_area * static_cast<T>(right_count);
        if (cost < min_cost) {
            min_cost = cost;
            best_axis = axis;
            best_cut_pos[axis] = cut_pos;
        }
    }
}

if (best_axis == -1) return false;

// Output results
cut_pos[0] = best_cut_pos[0];
cut_pos[1] = best_cut_pos[1];
cut_pos[2] = best_cut_pos[2];
*minCostAxis = best_axis;

return true;

